answer = (function() {
    if (gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin')) {
        return true;
    }
    if (gs.hasRole('x_1956908_wareho_0.technician') && current.assigned_to == gs.getUserID()) {
        return true;
    }
    if (gs.hasRole('x_1956908_wareho_0.staff') && current.reported_by == gs.getUserID()) {
        return true;
    }
    return false;
})();
